// Train/flight planning for drivers, by code. purpose:
//  replacement      -> pick up to 3 free drivers nearest the handover city and their best train/flight there
//  driver_return    -> get the current driver home (default: from the handover city to their home city)
//  positioning      -> any from_city -> to_city
// @include travel.js
const i = $('Start').first().json;
const c = $('Get context').first().json;
if (!c.found) return [{ json: { ok: false, error: c.error } }];
const s = c.snapshot;
const roster = (() => { try { return JSON.parse($('Roster').all().map((x) => x.json).find((r) => r.context)?.context || '{}').drivers || []; } catch (e) { return []; } })();
const now = Date.parse(s.snapshot_now);
// Nobody travels before a person approves: never earlier than now + the approval buffer (Settings page).
const earliest = Math.max(i.earliest ? Date.parse(i.earliest) : now, now + c.settings.approval_buffer_min * 6e4 + c.settings.booking_slack_min * 6e4);
if (Number.isNaN(earliest)) return [{ json: { ok: false, error: `earliest '${i.earliest}' is not an ISO time` } }];
const purpose = String(i.purpose || 'positioning').trim();
const last = (s.tracking_latest || []).slice(-1)[0];
const handover = cityKey(i.to_city) || (last ? nearestCity(s.pickup?.city, s.delivery?.city, last.progress_fraction)?.city : cityKey(s.pickup?.city));
const current = (s.assignments || []).find((a) => a.status === 'IN_PROGRESS') || (s.assignments || [])[0] || {};
const quotes = s.travel_options || [];
const failed = (c.plan_steps || []).filter((p) => ['book_train', 'book_flight'].includes(p.kind) && p.status === 'failed').map((p) => p.ref);
const brief = (r) => r.ok ? r.options.slice(0, 4) : [];

// The trip to the car counts against the replacement's working day; past the daily limit they rest first (Settings page numbers).
const workday = (arrives, used) => !arrives ? {} : { drive_used_min: Math.min(used, c.settings.daily_drive_max_min),
  can_start_driving: isoMin(Date.parse(arrives) + (used >= c.settings.daily_drive_max_min ? c.settings.daily_rest_min * 6e4 : 0)),
  hours_note: `trip uses ${Math.round(used / 6) / 10} h of the ${c.settings.daily_drive_max_min / 60} h day; pass drive_used_min and from_time=can_start_driving to check_journey` };
if (purpose === 'replacement') {
  if (!roster.length) return [{ json: { ok: false, error: 'Driver roster (REF-DRIVERS) not loaded; run seed.mjs.' } }];
  const free = roster.filter((d) => d.active && !d.busy && d.id !== current.driver_id && cityOf(d.home_city));
  const near = free.map((d) => ({ ...d, km: cityKey(d.home_city) === handover ? 0 : distKm(d.home_city, handover) })).sort((a, b) => a.km - b.km).slice(0, c.settings.replacement_drivers_checked);
  const candidates = near.map((d) => {
    if (d.km === 0) return { driver_id: d.id, name: d.display_name, home_city: d.home_city, km_to_handover: 0, travel: 'lives in the handover city: local transfer only', best_option: null, arrives: isoMin(earliest + 36e5), ...workday(isoMin(earliest + 36e5), 60) };
    const r = searchTravel({ quotes, from: d.home_city, to: handover, earliest, failed });
    const b = r.options?.[0], used = b ? Math.round((Date.parse(b.arrives) - Date.parse(b.leave_at || b.departs)) / 6e4) : 0;
    return { driver_id: d.id, name: d.display_name, home_city: d.home_city, km_to_handover: d.km, best_option: b || null, other_options: brief(r).slice(1, 3), arrives: b?.arrives || null, ...workday(b?.arrives, used) };
  }).sort((a, b) => (Date.parse(a.arrives) || Infinity) - (Date.parse(b.arrives) || Infinity));
  return [{ json: { ok: true, order_ref: c.order_ref, purpose, handover_city: handover, current_driver: current.driver || current.driver_id || null,
    rule: 'free = active and not on another job at snapshot time; nearest 3 by distance from home city, then ranked by earliest arrival',
    candidates, warning: 'mock_generated trains/flights are simulated; dataset_quote prices are quotes, not bookings. Nothing is booked until a person approves the plan.' } }];
}

let from = cityKey(i.from_city), to = cityKey(i.to_city);
if (purpose === 'driver_return') {
  from = from || handover || cityKey(s.delivery?.city);
  to = to || cityKey(roster.find((d) => d.id === current.driver_id)?.home_city);
}
if (!from || !to) return [{ json: { ok: false, error: 'from_city and to_city are required (driver home city unknown)' } }];
const r = searchTravel({ quotes, from, to, earliest, failed });
if (!r.ok) return [{ json: r }];
return [{ json: { ok: true, order_ref: c.order_ref, purpose, from_city: from, to_city: to, km: r.km, earliest: isoMin(earliest),
  recommended: r.recommended, summary: r.options[0] ? `Best: ${r.options[0].mode} ${r.options[0].provider} ${r.options[0].departs} -> arrives ${r.options[0].arrives}, EUR ${r.options[0].cost_eur} (${r.options[0].source}).` : 'No usable train or flight in the search range.',
  ranking: 'earliest arrival, then cost', options: r.options.slice(0, 6), not_usable: r.not_usable.slice(0, 8),
  warning: 'mock_generated trains/flights are simulated; dataset_quote prices are quotes, not bookings.' } }];
